var n=`1241-tassot`;var t=`world-1241`;var a=`HT`;var o=`central-america-caribbean`;var s=4;var r=111;var l={en:`Tassot`,ua:`Тассот`};var g={en:`Tassot is a dish from Haiti featuring beef sirloin, lime juice, garlic, yellow onion. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Тассот, страва кухні країни Гаїті з такими основними складниками: яловичий сирлойн, сік лайма, часник, жовта цибуля. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var d=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 80 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 80 хвилин.`,t:[`marinating`],m:80,i:[[`beef-sirloin`,800,`g`],[`lime-juice`,80,`ml`],[`garlic`,5,`clove`],[`ground-cloves`,2,`g`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 18 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 18 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:18,i:[[`canola-oil`,90,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,150,`g`],[`red-bell-pepper`,200,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,25,`g`],[`lime`,1,`pcs`]]}];var u={slug:n,id:t,country:`HT`,region:o,servings:4,minutes:111,title:l,text:g,steps:d};export{a as country,u as default,t as id,r as minutes,o as region,s as servings,n as slug,d as steps,g as text,l as title};